def transform(grid):
    import functools
    g = np.array(grid)
    H, W = g.shape
    cols = [int(c) for c in np.unique(g) if c != 0]

    # Noise colour: the one that breaks into the most separate pieces.
    ncomp = {c: len(components(g == c, diagonal=True)) for c in cols}
    noise = max(ncomp, key=lambda c: ncomp[c])
    frames = [c for c in cols if c != noise]

    def val(y, x):
        return g[y, x] if 0 <= y < H and 0 <= x < W else -1

    # Pairwise layering votes: votes[(a, b)] = times a passes straight over b.
    votes = {}
    for y in range(H):
        for x in range(W):
            a = int(g[y, x])
            if a not in frames:
                continue
            l, r, u, d = val(y, x-1), val(y, x+1), val(y-1, x), val(y+1, x)
            if l == r and l in frames and l != a and u == a and d == a:
                votes[(a, int(l))] = votes.get((a, int(l)), 0) + 1
            if u == d and u in frames and u != a and l == a and r == a:
                votes[(a, int(u))] = votes.get((a, int(u)), 0) + 1

    def count_cells(c):
        wall = g == c
        cand = (g != 0) & (g != c)   # foreign colours may hide this frame's wall
        w2 = wall.copy()
        for _ in range(10):
            before = w2.copy()
            for arr, cm, out in ((before, cand, w2), (before.T, cand.T, w2.T)):
                n = arr.shape[1]
                for i in range(arr.shape[0]):
                    j = 0
                    while j < n:
                        if cm[i, j] and not arr[i, j] and j > 0 and arr[i, j-1]:
                            k = j
                            while k < n and cm[i, k] and not arr[i, k]:
                                k += 1
                            L = k - j
                            if k < n and arr[i, k]:
                                ext = (j - 2 >= 0 and arr[i, j-2]) or (k + 1 < n and arr[i, k+1])
                                if L == 1 or (L <= 3 and ext):
                                    out[i, j:k] = True
                            j = max(k, j + 1)
                        else:
                            j += 1
            if np.array_equal(before, w2):
                break
        ys, xs = np.nonzero(wall)
        y0, y1, x0, x1 = ys.min(), ys.max(), xs.min(), xs.max()
        sub = ~w2[y0:y1+1, x0:x1+1]
        cnt = 0
        for comp in components(sub):
            if all(0 < p[0] < sub.shape[0]-1 and 0 < p[1] < sub.shape[1]-1 for p in comp):
                cnt += 1
        return cnt

    counts = {c: count_cells(c) for c in frames}

    def cmp(a, b):
        if counts[a] != counts[b]:
            return counts[a] - counts[b]
        va, vb = votes.get((a, b), 0), votes.get((b, a), 0)
        if va != vb:
            return 1 if va > vb else -1   # the frame on top goes later
        return a - b

    order = sorted(frames, key=functools.cmp_to_key(cmp))
    width = max(1, max(counts.values()))
    out = np.full((len(order), width), noise, dtype=int)
    emit(out.copy(), "Allocate one row per frame, filled with the noise colour")
    for i, c in enumerate(order):
        out[i, :counts[c]] = c
        emit(out.copy(), f"Frame colour {c} has {counts[c]} compartments: paint that many cells")
    return out
